import importlib.util
for m in ['matminer','torch','mendeleev','lightgbm','spglib','matgl','chgnet','m3gnet','jarvis','tensorflow','autogluon','rdkit']:
 print(m,bool(importlib.util.find_spec(m)))
from pymatgen.core import Structure
import pandas as pd
for name in ['cdft_topo_sp_eg_train.csv','cdft_topo_pool.csv']:
 df=pd.read_csv(name)
 print('\n',name)
 for _,r in df.iterrows():
  s=Structure.from_str(r.poscar,fmt='poscar')
  if name.endswith('pool.csv'):
   try: sg=s.get_space_group_info(symprec=.1)
   except: sg=('',0)
   print(r.candidate_id, '%10s'%r.formula,'n=%2s'%len(s),'vol/atom=%6.2f'%(s.volume/len(s)),str(sg), 'abc=',','.join('%.2f'%x for x in s.lattice.abc))
